//! Identity, versioning, canonical data and hashes.
//!
//! Three families of identifier exist and are never interchangeable:
//!
//! * **Entity ids** — UUID v7 newtypes generated by Kontor, persisted as
//!   lowercase hyphenated text.
//! * **Open keys** — deployment-defined names (`WorkProfileKey`, `PhaseKey`, …).
//!   They follow one conservative lexical rule so they are safe in paths, URLs,
//!   SQL and JSON; the core never enumerates their values.
//! * **External strings** — names and ids owned by a foreign system
//!   ([`ExternalName`], [`ExternalId`]). They are Unicode, may contain spaces
//!   and are *never* forced through the internal-key rule.

use std::collections::BTreeSet;
use std::fmt;

use serde::de::Error as _;
use serde::ser::Error as _;
use serde::{Deserialize, Deserializer, Serialize, Serializer};
use sha2::{Digest, Sha256};
use uuid::Uuid;

use crate::{DomainError, DomainResult};

pub use jiff::Timestamp;

/// Maximum length of an internal open key, in characters.
pub const MAX_KEY_LEN: usize = 128;
/// Maximum length of an external display name, in characters.
pub const MAX_EXTERNAL_NAME_LEN: usize = 512;
/// Maximum length of an opaque external identifier, in characters.
pub const MAX_EXTERNAL_ID_LEN: usize = 256;
/// Maximum length of a bounded free-text value, in characters.
pub const MAX_TEXT_LEN: usize = 65_536;
/// Maximum serialized size of a canonical document, in bytes.
pub const MAX_CANONICAL_BYTES: usize = 1_048_576;
/// Maximum nesting depth of a canonical document.
pub const MAX_CANONICAL_DEPTH: usize = 32;

// ---------------------------------------------------------------------------
// Entity ids
// ---------------------------------------------------------------------------

macro_rules! entity_ids {
    ($( $(#[$meta:meta])* $name:ident ),+ $(,)?) => {
        $(
            $(#[$meta])*
            ///
            /// A time-ordered UUID v7 generated by Kontor and persisted as
            /// lowercase hyphenated text.
            #[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Hash)]
            pub struct $name(Uuid);

            impl $name {
                /// Generate a fresh, time-ordered identifier.
                #[must_use]
                pub fn generate() -> Self {
                    Self(Uuid::now_v7())
                }

                /// Parse the canonical lowercase hyphenated text form.
                ///
                /// # Errors
                /// Rejects any non-canonical spelling and any UUID that is not
                /// version 7.
                pub fn parse(text: &str) -> DomainResult<Self> {
                    parse_entity_uuid(stringify!($name), text).map(Self)
                }

                /// Borrow the underlying UUID.
                #[must_use]
                pub const fn as_uuid(&self) -> &Uuid {
                    &self.0
                }
            }

            impl fmt::Display for $name {
                fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
                    fmt::Display::fmt(&self.0.as_hyphenated(), f)
                }
            }

            impl Serialize for $name {
                fn serialize<S: Serializer>(&self, serializer: S) -> Result<S::Ok, S::Error> {
                    serializer.serialize_str(&self.to_string())
                }
            }

            impl<'de> Deserialize<'de> for $name {
                fn deserialize<D: Deserializer<'de>>(deserializer: D) -> Result<Self, D::Error> {
                    let text = String::deserialize(deserializer)?;
                    Self::parse(&text).map_err(D::Error::custom)
                }
            }
        )+
    };
}

