fn parse_entity_uuid(subject: &'static str, text: &str) -> DomainResult<Uuid> {
    let uuid = Uuid::try_parse(text)
        .map_err(|_| DomainError::invalid(subject, "not a UUID in canonical text form"))?;
    if uuid.get_version_num() != 7 {
        return Err(DomainError::invalid(subject, "not a version 7 UUID"));
    }
    if uuid.as_hyphenated().to_string() != text {
        return Err(DomainError::invalid(
            subject,
            "not lowercase hyphenated canonical form",
        ));
    }
    Ok(uuid)
}

// ---------------------------------------------------------------------------
// Open keys
// ---------------------------------------------------------------------------

/// Validate one internal open key against the single lexical rule.
///
/// The rule is: 1–128 characters, ASCII only, first character `[a-z0-9]`,
/// remainder `[a-z0-9._-]`. That rejects uppercase, whitespace, control
/// characters, path separators, empty input and any input whose trimmed form
/// differs from itself.
///
/// # Errors
/// Returns [`DomainError::Invalid`] naming `subject`; the offending value is
/// never included.
pub fn validate_open_key(subject: &'static str, text: &str) -> DomainResult<()> {
    if text.is_empty() {
        return Err(DomainError::invalid(subject, "must not be empty"));
    }
    if text.chars().count() > MAX_KEY_LEN {
        return Err(DomainError::invalid(subject, "longer than 128 characters"));
    }
    let mut chars = text.chars();
    let first = chars.next().unwrap_or('\0');
    if !first.is_ascii_lowercase() && !first.is_ascii_digit() {
        return Err(DomainError::invalid(
            subject,
            "must start with a lowercase ASCII letter or digit",
        ));
    }
    for character in chars {
        let allowed = character.is_ascii_lowercase()
            || character.is_ascii_digit()
            || matches!(character, '.' | '_' | '-');
        if !allowed {
            return Err(DomainError::invalid(
                subject,
                "may contain only lowercase ASCII letters, digits, '.', '_' and '-'",
            ));
        }
    }
    reject_sensitive_text(subject, text)
}

macro_rules! open_keys {
    ($( $(#[$meta:meta])* $name:ident ),+ $(,)?) => {
        $(
            $(#[$meta])*
            ///
            /// An open, deployment-defined key. See [`validate_open_key`] for the
            /// lexical rule; the core never enumerates the legal values.
            #[derive(Debug, Clone, PartialEq, Eq, PartialOrd, Ord, Hash)]
            pub struct $name(String);

            impl $name {
                /// Parse and validate an open key.
                ///
                /// # Errors
                /// See [`validate_open_key`].
                pub fn parse(text: &str) -> DomainResult<Self> {
                    validate_open_key(stringify!($name), text)?;
                    Ok(Self(text.to_owned()))
                }

                /// Borrow the key text.
                #[must_use]
                pub fn as_str(&self) -> &str {
                    &self.0
                }
            }

            impl fmt::Display for $name {
                fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
                    f.write_str(&self.0)
                }
            }

            impl Serialize for $name {
                fn serialize<S: Serializer>(&self, serializer: S) -> Result<S::Ok, S::Error> {
                    serializer.serialize_str(&self.0)
                }
            }

            impl<'de> Deserialize<'de> for $name {
                fn deserialize<D: Deserializer<'de>>(deserializer: D) -> Result<Self, D::Error> {
                    let text = String::deserialize(deserializer)?;
                    Self::parse(&text).map_err(D::Error::custom)
                }
            }
        )+
    };
}

