// ---------------------------------------------------------------------------
// External (foreign-owned) strings
// ---------------------------------------------------------------------------

fn reject_control_characters(subject: &'static str, text: &str) -> DomainResult<()> {
    if text
        .chars()
        .any(|c| c.is_control() && !matches!(c, '\n' | '\t'))
    {
        return Err(DomainError::invalid(
            subject,
            "must not contain control characters",
        ));
    }
    Ok(())
}

/// A display name owned by an external system.
///
/// Unicode, may contain spaces, must be non-empty, trimmed, free of control
/// characters and at most [`MAX_EXTERNAL_NAME_LEN`] characters. External status
/// names, labels and human names use this type; they are never open keys.
#[derive(Debug, Clone, PartialEq, Eq, PartialOrd, Ord, Hash)]
pub struct ExternalName(String);

impl ExternalName {
    /// Parse an external display name.
    ///
    /// # Errors
    /// Rejects empty, untrimmed, oversized or control-bearing input.
    pub fn parse(text: &str) -> DomainResult<Self> {
        if text.is_empty() || text.trim() != text {
            return Err(DomainError::invalid(
                "ExternalName",
                "must be non-empty and free of leading or trailing whitespace",
            ));
        }
        if text.chars().count() > MAX_EXTERNAL_NAME_LEN {
            return Err(DomainError::invalid(
                "ExternalName",
                "longer than 512 characters",
            ));
        }
        if text.chars().any(char::is_control) {
            return Err(DomainError::invalid(
                "ExternalName",
                "must not contain control characters",
            ));
        }
        reject_sensitive_text("ExternalName", text)?;
        Ok(Self(text.to_owned()))
    }

    /// Borrow the name text.
    #[must_use]
    pub fn as_str(&self) -> &str {
        &self.0
    }
}

/// An opaque identifier owned by an external system.
///
/// External status ids, transition ids, issue keys, comment ids and account ids
/// are opaque to Kontor: their content is data, never a branch condition.
#[derive(Debug, Clone, PartialEq, Eq, PartialOrd, Ord, Hash)]
pub struct ExternalId(String);

impl ExternalId {
    /// Parse an opaque external identifier.
    ///
    /// # Errors
    /// Rejects empty, oversized, whitespace-bearing or control-bearing input.
    pub fn parse(text: &str) -> DomainResult<Self> {
        if text.is_empty() {
            return Err(DomainError::invalid("ExternalId", "must not be empty"));
        }
        if text.chars().count() > MAX_EXTERNAL_ID_LEN {
            return Err(DomainError::invalid(
                "ExternalId",
                "longer than 256 characters",
            ));
        }
        if text.chars().any(char::is_whitespace) {
            return Err(DomainError::invalid(
                "ExternalId",
                "must not contain whitespace",
            ));
        }
        if text.chars().any(char::is_control) {
            return Err(DomainError::invalid(
                "ExternalId",
                "must not contain control characters",
            ));
        }
        reject_sensitive_text("ExternalId", text)?;
        Ok(Self(text.to_owned()))
    }

    /// Borrow the identifier text.
    #[must_use]
    pub fn as_str(&self) -> &str {
        &self.0
    }
}

/// The *name* of one environment variable a child process is given.
///
/// A name is not a value: this type exists so that the one non-secret half of a
/// credential mapping has somewhere to live that can be persisted, listed and
/// put in a receipt, while the value it will carry never has a persisted type at
/// all.
///
/// The rule is the POSIX portable one — `[A-Z_][A-Z0-9_]*`, at most
/// [`MAX_KEY_LEN`] characters — which rules out `=`, whitespace, path
/// separators and the lowercase spellings a shell treats differently.
#[derive(Debug, Clone, PartialEq, Eq, PartialOrd, Ord, Hash)]
pub struct EnvironmentVariableName(String);

impl EnvironmentVariableName {
    /// Parse an environment variable name.
    ///
    /// # Errors
    /// Rejects empty, oversized, lowercase, digit-leading and punctuation-
    /// bearing input, and anything [`reject_sensitive_text`] refuses.
    pub fn parse(text: &str) -> DomainResult<Self> {
        if text.is_empty() {
            return Err(DomainError::invalid(
                "EnvironmentVariableName",
                "must not be empty",
            ));
        }
        if text.chars().count() > MAX_KEY_LEN {
            return Err(DomainError::invalid(
                "EnvironmentVariableName",
                "longer than 128 characters",
            ));
        }
        let mut characters = text.chars();
        let first = characters.next().unwrap_or('\0');
        if !first.is_ascii_uppercase() && first != '_' {
            return Err(DomainError::invalid(
                "EnvironmentVariableName",
                "must start with an uppercase ASCII letter or '_'",
            ));
        }
        for character in characters {
            if !character.is_ascii_uppercase() && !character.is_ascii_digit() && character != '_' {
                return Err(DomainError::invalid(
                    "EnvironmentVariableName",
                    "may contain only uppercase ASCII letters, digits and '_'",
                ));
            }
        }
        reject_sensitive_text("EnvironmentVariableName", text)?;
        Ok(Self(text.to_owned()))
    }

    /// Borrow the name text.
    #[must_use]
    pub fn as_str(&self) -> &str {
        &self.0
    }
}

/// A bounded free-text value (a field body, a comment body, a label).
///
/// Line endings are normalized to `\n` so the same content always hashes the
/// same way regardless of the platform that produced it.
#[derive(Debug, Clone, PartialEq, Eq, PartialOrd, Ord, Hash)]
pub struct BoundedText(String);

impl BoundedText {
    /// Parse and normalize a bounded text value.
    ///
    /// # Errors
    /// Rejects oversized input and control characters other than `\n` and `\t`.
    pub fn parse(text: &str) -> DomainResult<Self> {
        let normalized = normalize_line_endings(text);
        if normalized.chars().count() > MAX_TEXT_LEN {
            return Err(DomainError::invalid(
                "BoundedText",
                "longer than 65536 characters",
            ));
        }
        reject_control_characters("BoundedText", &normalized)?;
        reject_sensitive_text("BoundedText", &normalized)?;
        Ok(Self(normalized))
    }

    /// Borrow the normalized text.
    #[must_use]
    pub fn as_str(&self) -> &str {
        &self.0
    }
}

/// Normalize CRLF and lone CR to LF.
#[must_use]
pub fn normalize_line_endings(text: &str) -> String {
    if !text.contains('\r') {
        return text.to_owned();
    }
    let mut out = String::with_capacity(text.len());
    let mut chars = text.chars().peekable();
    while let Some(character) = chars.next() {
        if character == '\r' {
            if chars.peek() == Some(&'\n') {
                chars.next();
            }
            out.push('\n');
        } else {
            out.push(character);
        }
    }
    out
}

macro_rules! bounded_string_serde {
    ($($name:ident),+ $(,)?) => {
        $(
            impl fmt::Display for $name {
                fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
                    f.write_str(&self.0)
                }
            }

            impl Serialize for $name {
                fn serialize<S: Serializer>(&self, serializer: S) -> Result<S::Ok, S::Error> {
                    serializer.serialize_str(&self.0)
                }
            }

            impl<'de> Deserialize<'de> for $name {
                fn deserialize<D: Deserializer<'de>>(deserializer: D) -> Result<Self, D::Error> {
                    let text = String::deserialize(deserializer)?;
                    Self::parse(&text).map_err(D::Error::custom)
                }
            }
        )+
    };
}

bounded_string_serde!(
    ExternalName,
    ExternalId,
    BoundedText,
    IdempotencyKey,
    EnvironmentVariableName
);

// ---------------------------------------------------------------------------
// Versions, revisions, cursors
// ---------------------------------------------------------------------------

/// The persisted schema generation this binary understands.
///
/// Schema v1 accepts only `1`. A document or database claiming a newer schema is
/// refused rather than guessed at.
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Hash, Serialize)]
#[serde(transparent)]
pub struct SchemaVersion(u32);

/// The one schema version this binary implements.
pub const SCHEMA_VERSION: SchemaVersion = SchemaVersion(1);

impl SchemaVersion {
    /// Accept a document/database schema version.
    ///
    /// # Errors
    /// Rejects `0` and anything newer than [`SCHEMA_VERSION`].
    pub fn parse(value: u32) -> DomainResult<Self> {
        if value == 0 {
            return Err(DomainError::invalid("SchemaVersion", "must be positive"));
        }
        if value > SCHEMA_VERSION.0 {
            return Err(DomainError::invalid(
                "SchemaVersion",
                "is newer than this binary understands",
            ));
        }
        Ok(Self(value))
    }

    /// The numeric value.
    #[must_use]
    pub const fn get(self) -> u32 {
        self.0
    }
}

impl<'de> Deserialize<'de> for SchemaVersion {
    fn deserialize<D: Deserializer<'de>>(deserializer: D) -> Result<Self, D::Error> {
        Self::parse(u32::deserialize(deserializer)?).map_err(D::Error::custom)
    }
}

/// The version of one immutable specification revision.
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Hash, Serialize)]
#[serde(transparent)]
pub struct SpecVersion(u32);

impl SpecVersion {
    /// The first revision of any specification.
    pub const FIRST: Self = Self(1);

    /// Parse a positive specification version.
    ///
    /// # Errors
    /// Rejects `0`.
    pub fn parse(value: u32) -> DomainResult<Self> {
        if value == 0 {
            return Err(DomainError::invalid("SpecVersion", "must be positive"));
        }
        Ok(Self(value))
    }

    /// The numeric value.
    #[must_use]
    pub const fn get(self) -> u32 {
        self.0
    }

    /// The next revision.
    ///
    /// # Errors
    /// Rejects overflow rather than wrapping.
    pub fn next(self) -> DomainResult<Self> {
        self.0
            .checked_add(1)
            .map(Self)
            .ok_or_else(|| DomainError::invalid("SpecVersion", "overflowed"))
    }
}

impl<'de> Deserialize<'de> for SpecVersion {
    fn deserialize<D: Deserializer<'de>>(deserializer: D) -> Result<Self, D::Error> {
        Self::parse(u32::deserialize(deserializer)?).map_err(D::Error::custom)
    }
}

/// The optimistic-concurrency revision of a mutable aggregate.
///
/// Starts at `1` and only ever moves forward through a compare-and-swap.
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Hash, Serialize)]
#[serde(transparent)]
pub struct AggregateRevision(u64);

impl AggregateRevision {
    /// The revision of a freshly created aggregate.
    pub const INITIAL: Self = Self(1);

    /// Parse a stored revision.
    ///
    /// # Errors
    /// Rejects `0`.
    pub fn parse(value: u64) -> DomainResult<Self> {
        if value == 0 {
            return Err(DomainError::invalid(
                "AggregateRevision",
                "must start at 1 and be positive",
            ));
        }
        Ok(Self(value))
    }

    /// The numeric value.
    #[must_use]
    pub const fn get(self) -> u64 {
        self.0
    }

    /// The revision that a successful compare-and-swap writes.
    ///
    /// # Errors
    /// Rejects overflow rather than wrapping.
    pub fn next(self) -> DomainResult<Self> {
        self.0
            .checked_add(1)
            .map(Self)
            .ok_or_else(|| DomainError::invalid("AggregateRevision", "overflowed"))
    }

    /// Check a caller's expectation against the stored revision.
    ///
    /// # Errors
    /// Returns [`DomainError::RevisionConflict`] when they differ.
    pub fn expect(self, subject: &'static str, expected: Self) -> DomainResult<()> {
        if self == expected {
            Ok(())
        } else {
            Err(DomainError::RevisionConflict {
                subject,
                expected: expected.0,
                found: self.0,
            })
        }
    }
}

impl<'de> Deserialize<'de> for AggregateRevision {
    fn deserialize<D: Deserializer<'de>>(deserializer: D) -> Result<Self, D::Error> {
        Self::parse(u64::deserialize(deserializer)?).map_err(D::Error::custom)
    }
}

/// A positive, monotonically increasing event cursor.
///
/// Cursors are allocated by the store (a SQLite `INTEGER PRIMARY KEY
/// AUTOINCREMENT`) and are never reused, so a subscriber can resume strictly
/// *after* the cursor it already saw.
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Hash, Serialize)]
#[serde(transparent)]
pub struct EventCursor(i64);

impl EventCursor {
    /// Parse a stored cursor.
    ///
    /// # Errors
    /// Rejects zero and negative values.
    pub fn parse(value: i64) -> DomainResult<Self> {
        if value <= 0 {
            return Err(DomainError::invalid("EventCursor", "must be positive"));
        }
        Ok(Self(value))
    }

    /// The numeric value.
    #[must_use]
    pub const fn get(self) -> i64 {
        self.0
    }
}

impl<'de> Deserialize<'de> for EventCursor {
    fn deserialize<D: Deserializer<'de>>(deserializer: D) -> Result<Self, D::Error> {
        Self::parse(i64::deserialize(deserializer)?).map_err(D::Error::custom)
    }
}

/// A caller-supplied idempotency key.
#[derive(Debug, Clone, PartialEq, Eq, PartialOrd, Ord, Hash)]
pub struct IdempotencyKey(String);

impl IdempotencyKey {
    /// Parse an idempotency key.
    ///
    /// # Errors
    /// Rejects empty, untrimmed, oversized or control-bearing input.
    pub fn parse(text: &str) -> DomainResult<Self> {
        if text.is_empty() || text.trim() != text {
            return Err(DomainError::invalid(
                "IdempotencyKey",
                "must be non-empty and free of leading or trailing whitespace",
            ));
        }
        if text.chars().count() > MAX_EXTERNAL_ID_LEN {
            return Err(DomainError::invalid(
                "IdempotencyKey",
                "longer than 256 characters",
            ));
        }
        reject_control_characters("IdempotencyKey", text)?;
        reject_sensitive_text("IdempotencyKey", text)?;
        Ok(Self(text.to_owned()))
    }

    /// Borrow the key text.
    #[must_use]
    pub fn as_str(&self) -> &str {
        &self.0
    }
}

