/// An uppercase ISO-4217 currency code.
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Hash)]
pub struct CurrencyCode([u8; 3]);

impl CurrencyCode {
    /// Parse a three-letter uppercase currency code.
    ///
    /// # Errors
    /// Rejects anything that is not exactly three uppercase ASCII letters.
    pub fn parse(text: &str) -> DomainResult<Self> {
        let bytes = text.as_bytes();
        if bytes.len() != 3 || !bytes.iter().all(u8::is_ascii_uppercase) {
            return Err(DomainError::invalid(
                "CurrencyCode",
                "must be three uppercase ASCII letters",
            ));
        }
        Ok(Self([bytes[0], bytes[1], bytes[2]]))
    }

    /// Borrow the code text.
    #[must_use]
    pub fn as_str(&self) -> &str {
        // Constructed only from validated ASCII.
        std::str::from_utf8(&self.0).unwrap_or("XXX")
    }
}

impl fmt::Display for CurrencyCode {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.write_str(self.as_str())
    }
}

impl Serialize for CurrencyCode {
    fn serialize<S: Serializer>(&self, serializer: S) -> Result<S::Ok, S::Error> {
        serializer.serialize_str(self.as_str())
    }
}

impl<'de> Deserialize<'de> for CurrencyCode {
    fn deserialize<D: Deserializer<'de>>(deserializer: D) -> Result<Self, D::Error> {
        let text = String::deserialize(deserializer)?;
        Self::parse(&text).map_err(D::Error::custom)
    }
}

/// A monetary amount in integer minor units.
///
/// Money is never a floating-point value anywhere in Kontor, in Rust or in
/// SQLite.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
pub struct Money {
    /// Amount in the currency's minor units (for example: øre, cents).
    pub minor_units: u64,
    /// The currency the minor units are denominated in.
    pub currency: CurrencyCode,
}

// ---------------------------------------------------------------------------
// Timestamps
// ---------------------------------------------------------------------------

/// Parse a canonical UTC RFC 3339 timestamp.
///
/// The text must already be canonical UTC: a value that parses but renders
/// differently (an offset, a lowercase `z`, a redundant fraction) is rejected
/// rather than silently normalized, so stored text and in-memory value always
/// agree.
///
/// # Errors
/// Returns [`DomainError::Invalid`] for unparsable or non-canonical input.
pub fn parse_utc_timestamp(text: &str) -> DomainResult<Timestamp> {
    let timestamp: Timestamp = text
        .parse()
        .map_err(|_| DomainError::invalid("Timestamp", "not an RFC 3339 timestamp"))?;
    if timestamp.to_string() != text {
        return Err(DomainError::invalid(
            "Timestamp",
            "not in canonical UTC RFC 3339 form",
        ));
    }
    Ok(timestamp)
}

/// Render a timestamp in the canonical UTC form used for persistence.
#[must_use]
pub fn format_utc_timestamp(timestamp: Timestamp) -> String {
    timestamp.to_string()
}

// ---------------------------------------------------------------------------
// Hashes and canonical documents
// ---------------------------------------------------------------------------

/// A lowercase SHA-256 hex digest.
#[derive(Debug, Clone, PartialEq, Eq, PartialOrd, Ord, Hash)]
pub struct ContentHash(String);

impl ContentHash {
    /// Hash arbitrary bytes.
    #[must_use]
    pub fn of(bytes: &[u8]) -> Self {
        let mut hasher = Sha256::new();
        hasher.update(bytes);
        Self(hex::encode(hasher.finalize()))
    }

    /// Parse a stored digest.
    ///
    /// # Errors
    /// Rejects anything that is not 64 lowercase hex characters.
    pub fn parse(text: &str) -> DomainResult<Self> {
        if text.len() != 64
            || !text
                .bytes()
                .all(|b| b.is_ascii_digit() || (b'a'..=b'f').contains(&b))
        {
            return Err(DomainError::invalid(
                "ContentHash",
                "must be 64 lowercase hexadecimal characters",
            ));
        }
        Ok(Self(text.to_owned()))
    }

    /// Borrow the digest text.
    #[must_use]
    pub fn as_str(&self) -> &str {
        &self.0
    }
}

impl fmt::Display for ContentHash {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.write_str(&self.0)
    }
}

impl Serialize for ContentHash {
    fn serialize<S: Serializer>(&self, serializer: S) -> Result<S::Ok, S::Error> {
        serializer.serialize_str(&self.0)
    }
}

impl<'de> Deserialize<'de> for ContentHash {
    fn deserialize<D: Deserializer<'de>>(deserializer: D) -> Result<Self, D::Error> {
        let text = String::deserialize(deserializer)?;
        Self::parse(&text).map_err(D::Error::custom)
    }
}

/// A validated, canonically serialized JSON document and its digest.
///
/// Canonical form is: compact UTF-8, object keys sorted, array order preserved,
/// `\n` line endings inside strings, no non-finite numbers, a top-level object
/// carrying `schema_version`, bounded depth and bounded size. The document is
/// stored byte-for-byte together with [`ContentHash`] of exactly those bytes, so
/// a reordered or re-indented copy is detected instead of silently accepted.
///
/// Construction also rejects credential-, token- and identity-bearing material,
/// so an unredacted source envelope or persona document cannot reach SQL.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct CanonicalDocument {
    json: String,
    hash: ContentHash,
    schema_version: SchemaVersion,
}

impl CanonicalDocument {
    /// Canonicalize, validate and hash a JSON value.
    ///
    /// # Errors
    /// Returns [`DomainError`] when the value is not a `schema_version`-bearing
    /// object, exceeds the depth/size bounds, contains a non-finite number or
    /// carries sensitive material.
    pub fn from_value(value: &serde_json::Value) -> DomainResult<Self> {
        let schema_version = read_schema_version(value)?;
        reject_sensitive_material(value)?;
        let mut json = String::new();
        write_canonical(value, 0, &mut String::new(), &mut json)?;
        if json.len() > MAX_CANONICAL_BYTES {
            return Err(DomainError::invalid(
                "CanonicalDocument",
                "larger than 1 MiB once canonicalized",
            ));
        }
        let hash = ContentHash::of(json.as_bytes());
        Ok(Self {
            json,
            hash,
            schema_version,
        })
    }

    /// Canonicalize any serializable value.
    ///
    /// # Errors
    /// As [`CanonicalDocument::from_value`], plus serialization failures.
    pub fn from_serializable<T: Serialize>(value: &T) -> DomainResult<Self> {
        let value = serde_json::to_value(value).map_err(|_| {
            DomainError::invalid("CanonicalDocument", "is not serializable as JSON")
        })?;
        Self::from_value(&value)
    }

    /// Re-admit a document read back from storage, verifying both its canonical
    /// form and its recorded digest.
    ///
    /// # Errors
    /// Returns [`DomainError`] when the stored bytes are not canonical or the
    /// digest does not match.
    pub fn from_stored(json: &str, hash: &ContentHash) -> DomainResult<Self> {
        let value: serde_json::Value = serde_json::from_str(json)
            .map_err(|_| DomainError::invalid("CanonicalDocument", "is not valid JSON"))?;
        let document = Self::from_value(&value)?;
        if document.json != json {
            return Err(DomainError::invalid(
                "CanonicalDocument",
                "stored bytes are not in canonical form",
            ));
        }
        if &document.hash != hash {
            return Err(DomainError::invalid(
                "CanonicalDocument",
                "stored digest does not match the stored bytes",
            ));
        }
        Ok(document)
    }

    /// The canonical bytes, exactly as persisted.
    #[must_use]
    pub fn json(&self) -> &str {
        &self.json
    }

    /// The digest of [`CanonicalDocument::json`].
    #[must_use]
    pub const fn hash(&self) -> &ContentHash {
        &self.hash
    }

    /// The `schema_version` declared by the document.
    #[must_use]
    pub const fn schema_version(&self) -> SchemaVersion {
        self.schema_version
    }

    /// Parse the document back into a typed value.
    ///
    /// # Errors
    /// Returns [`DomainError`] when the document does not match `T`.
    pub fn deserialize<T: for<'de> Deserialize<'de>>(&self) -> DomainResult<T> {
        serde_json::from_str(&self.json).map_err(|_| {
            DomainError::invalid("CanonicalDocument", "does not match the target type")
        })
    }
}

impl Serialize for CanonicalDocument {
    fn serialize<S: Serializer>(&self, serializer: S) -> Result<S::Ok, S::Error> {
        let value: serde_json::Value = serde_json::from_str(&self.json)
            .map_err(|_| S::Error::custom("canonical document is not valid JSON"))?;
        value.serialize(serializer)
    }
}

impl<'de> Deserialize<'de> for CanonicalDocument {
    fn deserialize<D: Deserializer<'de>>(deserializer: D) -> Result<Self, D::Error> {
        let value = serde_json::Value::deserialize(deserializer)?;
        Self::from_value(&value).map_err(D::Error::custom)
    }
}

fn read_schema_version(value: &serde_json::Value) -> DomainResult<SchemaVersion> {
    let object = value.as_object().ok_or_else(|| {
        DomainError::invalid("CanonicalDocument", "top level must be a JSON object")
    })?;
    let raw = object.get("schema_version").ok_or_else(|| {
        DomainError::invalid("CanonicalDocument", "must declare `schema_version`")
    })?;
    let number = raw.as_u64().ok_or_else(|| {
        DomainError::invalid(
            "CanonicalDocument",
            "`schema_version` must be a positive integer",
        )
    })?;
    let narrowed = u32::try_from(number).map_err(|_| {
        DomainError::invalid("CanonicalDocument", "`schema_version` is out of range")
    })?;
    SchemaVersion::parse(narrowed)
}

fn write_canonical(
    value: &serde_json::Value,
    depth: usize,
    path: &mut String,
    out: &mut String,
) -> DomainResult<()> {
    if depth > MAX_CANONICAL_DEPTH {
        return Err(DomainError::invalid_at(
            "CanonicalDocument",
            path.clone(),
            "nested deeper than 32 levels",
        ));
    }
    match value {
        serde_json::Value::Null => out.push_str("null"),
        serde_json::Value::Bool(flag) => out.push_str(if *flag { "true" } else { "false" }),
        serde_json::Value::Number(number) => {
            if number.as_f64().is_some_and(|n| !n.is_finite()) {
                return Err(DomainError::invalid_at(
                    "CanonicalDocument",
                    path.clone(),
                    "contains a non-finite number",
                ));
            }
            out.push_str(&number.to_string());
        }
        serde_json::Value::String(text) => {
            let normalized = normalize_line_endings(text);
            let encoded = serde_json::to_string(&normalized).map_err(|_| {
                DomainError::invalid_at(
                    "CanonicalDocument",
                    path.clone(),
                    "contains an unencodable string",
                )
            })?;
            out.push_str(&encoded);
        }
        serde_json::Value::Array(items) => {
            out.push('[');
            for (index, item) in items.iter().enumerate() {
                if index > 0 {
                    out.push(',');
                }
                let restore = path.len();
                path.push_str(&format!("[{index}]"));
                write_canonical(item, depth + 1, path, out)?;
                path.truncate(restore);
            }
            out.push(']');
        }
        serde_json::Value::Object(members) => {
            let keys: BTreeSet<&String> = members.keys().collect();
            out.push('{');
            for (index, key) in keys.into_iter().enumerate() {
                if index > 0 {
                    out.push(',');
                }
                let encoded = serde_json::to_string(key).map_err(|_| {
                    DomainError::invalid_at(
                        "CanonicalDocument",
                        path.clone(),
                        "contains an unencodable object key",
                    )
                })?;
                out.push_str(&encoded);
                out.push(':');
                let restore = path.len();
                if !path.is_empty() {
                    path.push('.');
                }
                path.push_str(key);
                let member = members.get(key).unwrap_or(&serde_json::Value::Null);
                write_canonical(member, depth + 1, path, out)?;
                path.truncate(restore);
            }
            out.push('}');
        }
    }
    Ok(())
}

/// Object keys that may never appear in a persisted document.
///
/// Matching is exact on the normalized key (lowercased, `-`/`_`/space removed),
/// so legitimate names such as `token_budget` or `max_tokens` are unaffected.
const FORBIDDEN_KEYS: &[&str] = &[
    "secret",
    "secrets",
    "password",
    "passwd",
    "pwd",
    "token",
    "accesstoken",
    "refreshtoken",
    "idtoken",
    "bearertoken",
    "sessiontoken",
    "apikey",
    "apisecret",
    "clientsecret",
    "authorization",
    "credential",
    "credentials",
    "privatekey",
    "cookie",
    "ssn",
    "nationalid",
    "socialsecuritynumber",
    "birthnumber",
    "personnummer",
    "fodselsnummer",
    "patientid",
    "patientname",
];

/// Markers that indicate credential material, paired with the minimum number of
/// characters that must follow them.
///
/// The tail length is what keeps this usable: `sk-skill` is a perfectly good
/// open key, while `sk-` followed by twenty-four more characters is an API
/// token. Marker matching is defence in depth, not a vault — see the plan's
/// security note.
const SECRET_MARKERS: &[(&str, usize)] = &[
    ("-----begin", 0),
    ("private key", 0),
    ("private-key", 0),
    // A separator is required so an ordinary word starting "bearer" is safe.
    ("bearer ", 20),
    ("bearer-", 20),
    ("bearer_", 20),
    ("bearer:", 20),
    ("basic ", 20),
    ("basic-", 20),
    ("ghp_", 20),
    ("gho_", 20),
    ("github_pat_", 20),
    ("glpat-", 16),
    ("xoxb-", 16),
    ("xoxp-", 16),
    ("sk-", 24),
    ("sk_live_", 16),
    ("akia", 16),
    ("asia", 16),
    ("aiza", 20),
];

/// Inline assignments that carry a credential in an otherwise ordinary string,
/// such as a connection string or a copied command line.
const SECRET_ASSIGNMENTS: &[&str] = &[
    "password=",
    "passwd=",
    "pwd=",
    "api_key=",
    "apikey=",
    "secret=",
    "client_secret=",
    "access_token=",
    "refresh_token=",
    "token=",
    "authorization:",
];

fn has_marker(lowered: &str, marker: &str, min_tail: usize) -> bool {
    lowered
        .match_indices(marker)
        .any(|(index, _)| lowered.len() - index - marker.len() >= min_tail)
}

/// Whether the text embeds a password in a URL's userinfo (`scheme://u:p@host`).
fn has_url_credentials(lowered: &str) -> bool {
    let Some(scheme_end) = lowered.find("://") else {
        return false;
    };
    let authority = &lowered[scheme_end + 3..];
    let authority = authority.split('/').next().unwrap_or(authority);
    match authority.split_once('@') {
        Some((userinfo, _)) => userinfo.contains(':'),
        None => false,
    }
}

/// Reject credential, token or key material in any persisted string.
///
/// This is the single primitive every persisted string category goes through:
/// open keys, external names and ids, bounded text, idempotency keys and every
/// JSON string all call it, so no string-bearing value reaches SQL unscanned.
///
/// # Errors
/// Returns [`DomainError::SensitiveMaterial`] carrying only `path` — the
/// candidate value is never echoed, so a canary cannot leak into a log or a
/// test assertion.
pub fn reject_sensitive_text(path: &str, text: &str) -> DomainResult<()> {
    if text.is_empty() {
        return Ok(());
    }
    let lowered = text.to_lowercase();
    let hit = SECRET_MARKERS
        .iter()
        .any(|(marker, min_tail)| has_marker(&lowered, marker, *min_tail))
        || SECRET_ASSIGNMENTS
            .iter()
            .any(|marker| lowered.contains(marker))
        || has_url_credentials(&lowered);
    if hit {
        return Err(DomainError::SensitiveMaterial {
            path: path.to_owned(),
        });
    }
    Ok(())
}

/// Reject credentials, tokens and unredacted personal identifiers.
///
/// # Errors
/// Returns [`DomainError::SensitiveMaterial`] carrying only the structural path
/// of the offending node.
pub fn reject_sensitive_material(value: &serde_json::Value) -> DomainResult<()> {
    fn walk(value: &serde_json::Value, path: &mut String) -> DomainResult<()> {
        match value {
            serde_json::Value::Object(members) => {
                for (key, member) in members {
                    let normalized: String = key
                        .chars()
                        .filter(|c| !matches!(c, '-' | '_' | ' '))
                        .flat_map(char::to_lowercase)
                        .collect();
                    let restore = path.len();
                    if !path.is_empty() {
                        path.push('.');
                    }
                    path.push_str(key);
                    if FORBIDDEN_KEYS.contains(&normalized.as_str()) {
                        return Err(DomainError::SensitiveMaterial { path: path.clone() });
                    }
                    walk(member, path)?;
                    path.truncate(restore);
                }
                Ok(())
            }
            serde_json::Value::Array(items) => {
                for (index, item) in items.iter().enumerate() {
                    let restore = path.len();
                    path.push_str(&format!("[{index}]"));
                    walk(item, path)?;
                    path.truncate(restore);
                }
                Ok(())
            }
            serde_json::Value::String(text) => reject_sensitive_text(path, text),
            _ => Ok(()),
        }
    }

    walk(value, &mut String::new())
}
